<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../../components/admin/Breadcrumbs.vue';
import PageHeader from '../../../../components/admin/PageHeader.vue';
import FieldError from '../../../../components/FieldError.vue';
import AdminLayout from '../../../../layouts/AdminLayout.vue';

const form = useForm({ name: '', code: '', status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE' | 'ARCHIVED' });
const { t } = useI18n();
const submit = () => { if (!form.processing) form.post('/admin/inventory/locations'); };
const error = (field: 'name' | 'code' | 'status') => form.errors[field] ? t(`inventory.locations.errors.${field}`) : undefined;
</script>

<template>
    <Head :title="t('inventory.locations.create')" />
    <AdminLayout><section class="mx-auto grid w-full max-w-4xl gap-5 sm:gap-6">
        <Breadcrumbs :items="[{ label: t('nav.operations') }, { label: t('inventory.title'), href: '/admin/inventory' }, { label: t('inventory.locations.title'), href: '/admin/inventory/locations' }, { label: t('common.create') }]" />
        <PageHeader :title="t('inventory.locations.create')" :eyebrow="t('common.allCompany')" :description="t('inventory.locations.createDescription')"><template #actions><Link href="/admin/inventory/locations" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary">{{ t('inventory.locations.back') }}</Link></template></PageHeader>
        <aside class="rounded-md border border-admin-info-border bg-admin-info-bg px-4 py-3"><p class="text-sm font-semibold text-admin-text">{{ t('inventory.locations.createdNonDefault') }}</p><p class="mt-0.5 text-xs leading-5 text-admin-text-secondary">{{ t('inventory.locations.createdNonDefaultHelp') }}</p></aside>
        <form class="admin-card overflow-hidden" @submit.prevent="submit"><header class="border-b border-admin-border px-5 py-4 sm:px-6"><p class="admin-label text-admin-secondary">{{ t('inventory.locations.detailsSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('inventory.locations.details') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.locations.detailsHelp') }}</p></header><div class="grid gap-5 p-5 sm:p-6 md:grid-cols-2"><div><label for="location-name" class="mb-1.5 block text-sm font-semibold">{{ t('inventory.locations.name') }} <span class="text-admin-danger">*</span></label><input id="location-name" v-model="form.name" required autofocus maxlength="120" class="admin-control w-full px-3 text-sm" :aria-invalid="Boolean(form.errors.name)" /><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.locations.nameHelp') }}</p><FieldError :message="error('name')" /></div><div><label for="location-code" class="mb-1.5 block text-sm font-semibold">{{ t('inventory.locations.code') }} <span class="text-admin-danger">*</span></label><input id="location-code" v-model="form.code" required maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9_-]*" placeholder="MAIN" class="admin-control w-full px-3 font-mono text-sm uppercase" :aria-invalid="Boolean(form.errors.code)" /><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.locations.codeHelp') }}</p><FieldError :message="error('code')" /></div><div class="md:col-span-2"><label for="location-status" class="mb-1.5 block text-sm font-semibold">{{ t('common.status') }} <span class="text-admin-danger">*</span></label><select id="location-status" v-model="form.status" required class="admin-control w-full px-3 text-sm md:max-w-sm" :aria-invalid="Boolean(form.errors.status)"><option value="ACTIVE">{{ t('status.ACTIVE') }}</option><option value="INACTIVE">{{ t('status.INACTIVE') }}</option><option value="ARCHIVED">{{ t('status.ARCHIVED') }}</option></select><p class="mt-1 text-xs text-admin-neutral">{{ t('inventory.locations.statusHelp') }}</p><FieldError :message="error('status')" /></div></div><footer class="flex flex-col-reverse gap-2 border-t border-admin-border bg-admin-canvas px-5 py-4 sm:flex-row sm:justify-end sm:px-6"><Link href="/admin/inventory/locations" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold text-admin-text-secondary">{{ t('common.cancel') }}</Link><button type="submit" :disabled="form.processing" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-60">{{ form.processing ? t('common.creating') : t('inventory.locations.create') }}</button></footer></form>
    </section></AdminLayout>
</template>
